create table if not exists public.baseball_connections_puzzles (
  id          uuid        primary key default gen_random_uuid(),
  puzzle_id   text        not null unique,
  groups_json jsonb       not null,
  sort_order  smallint    not null,
  created_at  timestamptz not null default now()
);
alter table public.baseball_connections_puzzles enable row level security;
do $$ begin
  if not exists (select 1 from pg_policies where schemaname = 'public' and tablename = 'baseball_connections_puzzles' and policyname = 'Public read-only') then
    create policy "Public read-only" on public.baseball_connections_puzzles for select to anon, authenticated using (true);
  end if;
end $$;
create index if not exists baseball_connections_puzzles_sort_order_idx on public.baseball_connections_puzzles (sort_order);
on conflict (puzzle_id) do update set
  groups_json = excluded.groups_json,
  sort_order  = excluded.sort_order;
